"""Шаблон ЭТАЛОНА. Рабочее решение с доктестами и объяснением.

Отличие от стаба: тело написано, а в docstring есть не только примеры,
но и одно-два предложения о том, ПОЧЕМУ решение корректно.
"""


def solve(nums: list[int], target: int) -> int:
    """Одна строка: что делает функция.

    Идея: <почему этот подход работает — 1-2 предложения, а не пересказ кода>.

    Время O(n), память O(1).

    >>> solve([1, 2, 3], 2)
    2
    >>> solve([], 0)
    0
    """
    total = 0
    for x in nums:
        if x <= target:
            total += 1
    return total
